import{_ as o,o as a,c as s,a2 as p}from"./chunks/framework.BZAK_utg.js";const u=JSON.parse('{"title":"ArchLinux系统安装与配置","description":"","frontmatter":{"title":"ArchLinux系统安装与配置","date":"2019-12-11","categories":["安装配置","操作系统"],"tags":["Linux"],"prevTitle":"ArchLinux下LAMP的安装","prevLink":"./ArchLinux下LAMP的安装.html","nextTitle":"ArchLinux常用软件","nextLink":"./ArchLinux常用软件.html"},"headers":[],"relativePath":"posts/安装配置/ArchLinux系统安装与配置.md","filePath":"posts/安装配置/ArchLinux系统安装与配置.md"}'),n={name:"posts/安装配置/ArchLinux系统安装与配置.md"};function c(t,e,d,i,r,l){return a(),s("div",null,[...e[0]||(e[0]=[p(`<h1 id="archlinux系统安装与配置" tabindex="-1">ArchLinux系统安装与配置 <a class="header-anchor" href="#archlinux系统安装与配置" aria-label="Permalink to &quot;ArchLinux系统安装与配置&quot;">​</a></h1><p>ArchLinux基础环境的安装，参考自ArchLinux官方Wiki的<a href="https://wiki.archlinuxcn.org/wiki/%E5%AE%89%E8%A3%85%E6%8C%87%E5%8D%97" target="_blank" rel="noreferrer">安装指南</a>。</p><blockquote><p>最新版本的ArchLinux镜像已经默认集成了<code>archinstall</code>安装脚本，可快速完成ArchLinux基础环境的安装，详见<a href="https://wiki.archlinuxcn.org/wiki/Archinstall" target="_blank" rel="noreferrer">官方文档</a>。</p></blockquote><h2 id="一、硬盘分区" tabindex="-1">一、硬盘分区 <a class="header-anchor" href="#一、硬盘分区" aria-label="Permalink to &quot;一、硬盘分区&quot;">​</a></h2><p><strong>1. 创建引导分区和根分区</strong></p><p><code>fdisk /dev/sda</code> （进入第一个硬盘）</p><p><code>g</code> （如果是全新硬盘，使用g创建新的gpt分区表）</p><p><code>n</code> <code>回车</code> <code>回车</code> <code>+500M</code> （创建新的分区作为引导分区，大小为500M）</p><p><code>t</code> <code>1</code> （修改分区类型为EFI System）</p><p><code>n</code> <code>回车</code> <code>回车</code> <code>+10G</code> （创建新的分区作为根分区，大小为10G）</p><p><code>p</code> （打印所有更改）</p><p><code>w</code> （保存所有更改）</p><p><strong>2. 格式化分区</strong></p><p><code>mkfs.fat -F32 /dev/sda1</code> （格式化引导分区）</p><p><code>mkfs.ext4 /dev/sda2</code> （格式化根分区）</p><ul><li>挂载分区</li></ul><p><code>mount /dev/sda2 /mnt</code> （挂载根分区到airrootfs下的mnt目录）</p><p><code>mkdir /mnt/boot</code> （在airrootfs下的mnt目录创建boot子目录）</p><p><code>mount /dev/sda2 /mnt/boot</code> （挂载引导分区到airrootfs下的mnt/boot目录）</p><blockquote><p>（注意！！！chroot之前，所有的操作均是在内存中进行，airrootfs挂载为系统根目录，chroot在后面有介绍）</p></blockquote><hr><h2 id="二、联网安装" tabindex="-1">二、联网安装 <a class="header-anchor" href="#二、联网安装" aria-label="Permalink to &quot;二、联网安装&quot;">​</a></h2><p><strong>1. 联网</strong></p><p><code>wifi-menu</code> （使用无线局域网）</p><p><code>dhcp</code> （使用自动拨号）</p><blockquote><p>（注意！使用手机开热点时，电脑可能不能正常解析DNS服务器，需要手动设置。）</p></blockquote><p><code>vim /etc/resolv.conf</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------</span></span>
<span class="line"><span>nameserver 114.114.114.114）</span></span>
<span class="line"><span>--------------------------------------------</span></span></code></pre></div><p><strong>2. 选择镜像源</strong></p><p><code>vim /etc/pacman.d/mirrolist</code> （修改镜像源）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------------</span></span>
<span class="line"><span>Server = http://mirrors.neusoft.edu.cn/archlinux/$repo/os/$arch （选择镜像源）</span></span>
<span class="line"><span>--------------------------------------------------</span></span></code></pre></div><blockquote><p>（大多数镜像源格式一致，只需要更改http与archlinux之间的内容即可）</p></blockquote><p><strong>3. 安装基本包</strong></p><p><code>pacstrap /mnt base base-devel</code></p><hr><h2 id="三、配置基础系统" tabindex="-1">三、配置基础系统 <a class="header-anchor" href="#三、配置基础系统" aria-label="Permalink to &quot;三、配置基础系统&quot;">​</a></h2><p><strong>1. 设置分区自动挂载</strong>（生成fstab文件）</p><p><code>genfstab -L /mnt &gt;&gt; /mnt/etc/fstab</code> （自动生成fstab文件，如若按tab未正常补齐，说明前面安装错误）</p><p><code>cat /mnt/etc/fstab</code> （查看fstab文件是否生成成功，若内容不正确，会导致下次无法启动系统！）</p><p><strong>2. 更换根目录挂载点，系统操作权转移</strong>（Chroot）</p><p><code>arch-chroot /mnt</code> （将根目录挂载点由由airrootfs变为/dev/sda2（即airrootfs下的mnt目录））</p><blockquote><p>（注意！！！chroot之前，大部分操作是在内存中进行，chroot之后，一切操作均在硬盘上进行）</p></blockquote><p><strong>3. 趁现在有网，将必须的安装包下载下来</strong></p><p><code>pacman -S vim dialog wpa_supplicant ntfs-3g networkmanager</code> （安装vim和网络相关的软件）</p><p><code>pacman -S intel-ucode</code> （安装intel相关驱动）</p><p><code>pacman -S os-prober grub efibootmgr</code>（安装引导相关软件）</p><p><strong>4. 设置Locale，主机名，Root密码</strong></p><p><code>vim /etc/locale.gen</code> （去掉相关注释）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------</span></span>
<span class="line"><span>en_US.UTF-8</span></span>
<span class="line"><span>zh_CN.UTF-8</span></span>
<span class="line"><span>zh_HK.UTF-8</span></span>
<span class="line"><span>zh_TW.UTF-8</span></span>
<span class="line"><span>--------------------------------------------</span></span></code></pre></div><p><code>locale-gen</code> （使local生效）</p><p><code>vim /etc/locale.conf</code> （编辑本地化文件）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------</span></span>
<span class="line"><span>LANG=en_US.UTF-8 （设置默认本地本地化标准）</span></span>
<span class="line"><span>--------------------------------------------</span></span></code></pre></div><p><code>echo Archlinux &gt; /etc/hostname</code> （设置主机名）</p><p><code>vim /etc/hosts</code> （添加主机名对应信息，非必要）</p><p><code>passwd</code> （设置root密码）</p><p><strong>5. 新建用户并赋予其sudo权限</strong></p><p><code>useradd -m -G wheel luanrz</code> （创建用户luanrz）</p><p><code>passwd luanrz</code> （修改luanrz密码）</p><p><code>pacman -S sudo</code> （安装sudo）</p><p><code>vim /etc/sudoers</code> （配置sudo）</p><p><strong>6. 设置时间</strong></p><p><code>timedatectl set-ntp true</code> （更新系统时间）（在前面设置）</p><p><code>ln -sf /usr/share/zoneinfo/Asia/Shanghai /etc/localtime</code> （设置时区为上海）</p><p><code>hwclock --systohc --utc</code> （设置时间标准为UTC）</p><p><strong>7. 部署启动文件</strong></p><p><code>grub-install --target=x86_64-efi --efi-directory=/boot --bootloader-id=arch</code> （在引导分区安装grub）</p><p><code>vim /etc/lvm/lvm.conf</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------</span></span>
<span class="line"><span>use_lvmetad = 0 （大约在40%处，将1改为0）</span></span>
<span class="line"><span>--------------------------------------------</span></span></code></pre></div><p><code>grub-mkconfig -o /boot/grub/grub.cfg</code> （生成grub配置文件）</p><p><strong>8. 创建交换文件</strong>（可选）</p><p><code>fallocate -l 4G /swapfile</code></p><p><code>chmod 600 /swapfile</code></p><p><code>mkswap /swapfile</code></p><p><code>swapon /swapfile</code></p><p><code>vim /etc/fstab</code></p><p><strong>9. 重启系统</strong></p><p><code>exit</code></p><p><code>reboot</code></p><p>至此，ArchLinux基础环境已经安装成功了！基础软件的安装与配置过程，请参考后续步骤。</p>`,79)])])}const g=o(n,[["render",c]]);export{u as __pageData,g as default};
